  ["SkillCategory:9"] = { "二次スキル", 0x047ee6cb, "." },
  ["SkillLineDescription:129"] = { "First Aidスキルが高いほど、より高レベルのFirst Aidのアビリティを習得できます。First Aidのアビリティは、世界各地のトレーナーから習得できるほか、クエストやモンスターのドロップからも入手できます。", 0x74fc8993, "." },
  ["SkillLineDescription:162"] = { "スキルが高いほど、攻撃の命中率が上がります。", 0x42f6ba0b, "." },
  ["SkillLineDescription:164"] = { "Blacksmithingスキルが高いほど、より高レベルのBlacksmithingのプランを習得できます。Blacksmithingのプランは、世界各地のトレーナーから習得できるほか、クエストやモンスターからも入手できます。", 0x98ae6496, "." },
  ["SkillLineDescription:165"] = { "Leatherworkingスキルが高いほど、より高レベルのLeatherworkingのパターンを習得できます。Leatherworkingのパターンは、世界各地のトレーナーから習得できるほか、クエストやモンスターからも入手できます。", 0x8e47360f, "." },
  ["SkillLineDescription:171"] = { "Alchemyスキルが高いほど、より高レベルのAlchemyのレシピを習得できます。Alchemyのレシピは、世界各地のトレーナーから習得できるほか、クエストやモンスターからも入手できます。", 0xee63324e, "." },
  ["SkillLineDescription:182"] = { "Herbalismスキルが高いほど、世界各地のより採集の難しいハーブを採集できます。特定のハーブを採集できない場合は、低レベルの地域でより採集しやすいハーブを採集してスキルを上げてください。", 0x3df49217, "." },
  ["SkillLineDescription:185"] = { "Cookingスキルが高いほど、より高レベルの料理のレシピを習得できます。レシピは、世界各地のトレーナーから習得できるほか、クエストやモンスターのドロップからも入手できます。", 0xb681ef9e, "." },
  ["SkillLineDescription:186"] = { "Miningスキルが高いほど、世界各地のより採掘の難しい鉱脈を採掘できます。特定の鉱石を採掘できない場合は、低レベルの地域でより採掘しやすい鉱石を採掘してスキルを上げてください。", 0xb959646e, "." },
  ["SkillLineDescription:197"] = { "Tailoringスキルが高いほど、より高レベルのTailoringのパターンを習得できます。Tailoringのパターンは、世界各地のトレーナーから習得できるほか、クエストやモンスターからも入手できます。", 0xfafad077, "." },
  ["SkillLineDescription:202"] = { "Engineeringスキルが高いほど、より高レベルのEngineeringの設計図を習得できます。設計図は、世界各地のトレーナーから習得できるほか、クエストやモンスターからも入手できます。", 0x486c03fa, "." },
  ["SkillLineDescription:2851"] = { "Engravingスキルが高いほど、より高レベルのルーンを習得し、アーマーや武器に付与できます。ルーンは世界各地に隠されています。", 0xfe6ab65d, "." },
  ["SkillLineDescription:293"] = { "プレートアーマーを装備できます。", 0x0b8e987b, "." },
  ["SkillLineDescription:2933"] = { "スキルが高いほど、より高レベルのレシピを習得できます。レシピは、世界各地のトレーナーから習得できるほか、クエストやモンスターのドロップからも入手できます。", 0x3af0a194, "." },
  ["SkillLineDescription:333"] = { "Enchantingスキルが高いほど、より強力なフォーミュラを習得できます。フォーミュラは、世界各地のトレーナーから習得できるほか、クエストやモンスターからも入手できます。", 0x4bddfa1e, "." },
  ["SkillLineDescription:356"] = { "Fishingスキルが高いほど、世界各地の水域で魚を釣り上げる確率が上がります。ある地域で魚がなかなか釣れない場合は、より低レベルの地域へ移動するか、釣り用のルアーを購入して再挑戦してください。", 0x0904c11f, "." },
  ["SkillLineDescription:393"] = { "Skinningスキルが高いほど、世界各地のより高レベルのモンスターから皮をはぎ取れます。スキルが100を超えたら、スキルを5で割ると、皮をはげるモンスターの最高レベルがわかります。", 0xea74f326, "." },
  ["SkillLineDescription:413"] = { "メイルアーマーを装備できます。", 0x6420472b, "." },
  ["SkillLineDescription:414"] = { "レザーアーマーを装備できます。", 0x41f839b7, "." },
  ["SkillLineDescription:415"] = { "クロースアーマーを装備できます。", 0x9fa01724, "." },
  ["SkillLineDescription:43"] = { "武器スキルが高いほど、攻撃の命中率が上がります。", 0xda190ba7, "." },
  ["SkillLineDescription:433"] = { "盾を使用できます。", 0x4bcd6a96, "." },
  ["SkillLineDescription:473"] = { "格闘武器を使用できます。命中率はUnarmedスキルによって決まります。", 0x60c5ba93, "." },
  ["SkillLineDescription:762"] = { "Ridingスキルが高いほど、より速く、よりエキゾチックな動物に騎乗できます。", 0x6d72eabd, "." },
  ["SkillLineDescription:777"] = { "あなたのマウント。", 0xbab16f9e, "." },
  ["SkillLineDescription:778"] = { "あなたのペット。", 0xe8329dcf, "." },
  ["SkillLineDescription:95"] = { "防御が高いほど攻撃を受けにくくなり、モンスターがクラッシングブローを与える確率も下がります。", 0xd43acde0, "." },
